test('private copy and photos can be stored without guessed product IDs but activation is blocked',async()=>{const db=await setup();try{const s=snapshot();s.products=[];s.scopeHash=hash({...s.version===2?{recipientCriteria:s.recipientCriteria}:{},templateRevision:s.template.revision,templateHash:hash(s.template),signatureHash:hash(s.signature),products:[],images:s.images.map(({id,sha256,bytes})=>({id,sha256,bytes}))});delete s.contentHash;s.contentHash=hash(s);const p=await rpc(db,'configure',owner,0,{data:s},policy);assert.equal(p.enabled,false);assert.equal(p.send_enabled,false);await assert.rejects(()=>rpc(db,'schedule',owner,1),/product_scope_missing/);assert.equal((await query(db,'select count(*)::int n from sanji_outbox'))[0].n,0);assert.equal((await query(db,"select count(*)::int n from sanji_records where kind='deal'"))[0].n,2);}finally{await db.close();}});
function sealSnapshot(s){const scope={...s.version===2?{recipientCriteria:s.recipientCriteria}:{},templateRevision:s.template.revision,templateHash:hash(s.template),signatureHash:hash(s.signature),products:s.products,images:s.template.requiredInlineImageIds.map(id=>{const {sha256,bytes}=s.images.find(i=>i.id===id);return {id,sha256,bytes};})};if(s.productMode==='approved_campaign_assets')Object.assign(scope,{productMode:s.productMode,campaignProducts:s.campaignProducts});s.scopeHash=hash(scope);delete s.contentHash;s.contentHash=hash(s);return s;}
function assetSnapshot(){const s=snapshot();s.productMode='approved_campaign_assets';s.products=[];s.campaignProducts=['마라쫀득빵','짬뽕쫀득빵'].map((name,i)=>({name,approvalSource:'exact user approved copy and two supplied product images'}));return sealSnapshot(s);}
