test('expired Instagram supplemental review guard prevents fallback to an older native email',async()=>{const db=await setup();try{const x=await ready(db,{platform:'instagram',snapshot:assetSnapshot()});await query(db,'insert into sanji_daily_supply_instagram_review_guards values($1,$2,$3,clock_timestamp())',[owner,'mara-jjamppong-bread',cid]);await assert.rejects(()=>reserve(db,x),/no native fallback/);assert.equal((await query(db,'select count(*)::int n from sanji_outbox'))[0].n,0);}finally{await db.close();}});
async function installPublication(db,x){const sourceId='99999999-9999-4999-8999-999999999999',at=new Date().toISOString(),expiry=new Date(Date.now()+3600000).toISOString(),url='https://example.com/contact';const affiliation={verified:true,independentlyVerified:true,creatorKey:x.k,officialUrl:url,method:'manual_cross_reference',reviewedBy:owner,sourceUrl:'https://example.com/creators',sourceText:'Creator official channel '+x.k.split(':')[1],checkedAt:at};const stored={creatorKey:x.k,url,sourceRecordId:cid,sourceUrl:affiliation.sourceUrl,sourceText:affiliation.sourceText,reviewedBy:owner,checkedAt:at},policyReview={exactUrl:url,decision:'allow_public_get',reviewedBy:owner,reviewedAt:at,expiresAt:expiry,noLoginOrChallenge:true,noAccessRestriction:true,maxRequestsPerDay:1,termsUrl:'https://example.com/terms',termsExcerpt:'Public business source review',robotsUrl:'https://example.com/robots.txt',robotsExcerpt:'Allow /contact',accessRationale:'Specific public collaboration contact'};await query(db,"insert into sanji_contact_source_versions(owner,source_id,revision,creator_key,source_url,source_kind,state,stored_link,policy_review,affiliation) values($1,$2,1,$3,$4,'official_website','reviewed',$5,$6,$7)",[owner,sourceId,x.k,url,stored,policyReview,affiliation]);const evidence={creatorKey:x.k,address:recipient,sourceUrl:url,sourceText:'협업 '+recipient,sourceKind:'official_website',checkedAt:at,verified:true,purpose:'business_collaboration',accessMethod:'public_source_review',ambiguous:false,affiliation:{verified:true,creatorKey:x.k,sourceUrl:affiliation.sourceUrl,sourceText:affiliation.sourceText,checkedAt:at},enrichment:{sourceId,revision:1,status:'publication_verified',publicationEvidenceOnly:true}};const observation={owner,creatorKey:x.k,status:'publication_verified',evidence,sourceVersions:[{sourceId,revision:1}],blockedSources:[],recordedAt:at,validUntil:expiry,publicationEvidenceOnly:true};await query(db,"insert into sanji_contact_observations(owner,creator_key,kind,payload) values($1,$2,'publication',$3)",[owner,x.k,observation]);await query(db,"update sanji_records set data=jsonb_set(data,'{dailyOutreachEvidence,contactEvidence}','[]') where id=$1",[cid]);const raw=(await query(db,'select * from sanji_records where id=$1',[cid]))[0],{adaptYoutubeRecord}=await import('../supabase/functions/creator-daily-outreach/repository.mjs'),{qualifyOutreachCandidate}=await import('../supabase/functions/creator-daily-outreach/domain.mjs');const qualified=qualifyOutreachCandidate({...adaptYoutubeRecord(raw),contactEvidence:[evidence]});assert.equal(qualified.eligible,true);assert.equal(qualified.contactReason,null);await query(db,'update sanji_daily_outreach_candidates set snapshot=$1',[{...qualified.candidate,status:'awaiting_dispatch_review'}]);return {observation,sourceId};}
test('current versioned publication augments missing manual email and blocks revocation, negative or changed observations',async()=>{const db=await setup();try{const x=await ready(db,{snapshot:assetSnapshot()}),p=await installPublication(db,x),r=await reserve(db,x);for(const mutation of [async()=>query(db,"update sanji_contact_source_versions set state='revoked'"),async()=>query(db,"update sanji_contact_source_versions set revision=2"),async()=>query(db,"update sanji_contact_source_versions set policy_review=jsonb_set(policy_review,'{noAccessRestriction}','false')"),async()=>query(db,"insert into sanji_contact_observations(owner,creator_key,kind,payload) values($1,$2,'publication',$3)",[owner,x.k,{...p.observation,status:'public_email_not_present',evidence:{...p.observation.evidence,verified:false,address:''}}]),async()=>query(db,"insert into sanji_contact_observations(owner,creator_key,kind,payload) values($1,$2,'publication',$3)",[owner,x.k,p.observation])]){await db.exec('begin');await mutation();await assert.rejects(()=>begin(db,x,r));await db.exec('rollback');}assert.equal((await begin(db,x,r)).ready,true);await finalize(db,x,r,'accepted',{id:'publication-receipt',threadId:'publication-thread'});}finally{await db.close();}});
test('manual no-email→fresh publication→specific recipient basis→real JS/SQL mock dispatch',()=>dispatchIntegration(true,false,true));
async function installInstagramPublication(db,x){const sourceId='99999999-9999-4999-8999-999999999999',at=new Date(Date.now()-500).toISOString(),expiry=new Date(Date.now()+3600000).toISOString(),url='https://www.instagram.com/foodperson/';const affiliation={verified:true,independentlyVerified:true,creatorKey:x.k,officialUrl:url,method:'manual_cross_reference',reviewedBy:owner,sourceUrl:'https://example.com/creators',sourceText:'Creator foodperson official profile',checkedAt:at},stored={creatorKey:x.k,url,sourceRecordId:cid,sourceUrl:affiliation.sourceUrl,sourceText:affiliation.sourceText,reviewedBy:owner,checkedAt:at},policyReview={exactUrl:url,decision:'allow_existing_official_bio',reviewedBy:owner,reviewedAt:at,expiresAt:expiry,noLoginOrChallenge:true,noAccessRestriction:true,maxRequestsPerDay:1,termsUrl:'https://example.com/terms',termsExcerpt:'Existing public bio review',robotsUrl:'https://example.com/robots.txt',robotsExcerpt:'No new network access',accessRationale:'Existing official collaboration bio'};await query(db,"insert into sanji_contact_source_versions(owner,source_id,revision,creator_key,source_url,source_kind,state,stored_link,policy_review,affiliation) values($1,$2,1,$3,$4,'instagram_public_bio','reviewed',$5,$6,$7)",[owner,sourceId,x.k,url,stored,policyReview,affiliation]);const evidence={creatorKey:x.k,address:recipient,sourceUrl:url,sourceText:'협업 '+recipient,sourceKind:'instagram_public_bio',checkedAt:at,verified:true,purpose:'business_collaboration',accessMethod:'public_source_review',ambiguous:false,affiliation:null,enrichment:{sourceId,revision:1,status:'publication_verified',publicationEvidenceOnly:true}},observation={owner,creatorKey:x.k,status:'publication_verified',evidence,sourceVersions:[{sourceId,revision:1}],blockedSources:[],recordedAt:at,validUntil:expiry,publicationEvidenceOnly:true},detail={bio:'먹방 크리에이터\n협업\n  '+recipient,bio_source_url:url,bio_content_available:true,bio_checked_at:at};await query(db,"insert into sanji_creator_evidence(owner,creator_id,source_kind,source_provider,source_url,source_ref,detail) values($1,$2,'public_bio','instagram_official',$3,'business_discovery',$4)",[owner,cid,url,detail]);await query(db,"insert into sanji_contact_observations(owner,creator_key,kind,payload) values($1,$2,'publication',$3)",[owner,x.k,observation]);await query(db,"update sanji_creator_evidence set detail=jsonb_set(detail,'{contactEvidence}','[]') where source_kind='daily_outreach_review'");const c=(await query(db,'select snapshot from sanji_daily_outreach_candidates'))[0].snapshot;await query(db,'update sanji_daily_outreach_candidates set snapshot=$1',[{...c,contact:{...evidence,key:'firstlast@gmail.com'}}]);return {detail,url,at};}
test('Instagram publication rereads latest authoritative bio before grant and rejects removal, changed context and conflicting timestamps',async()=>{const db=await setup();try{const x=await ready(db,{platform:'instagram',snapshot:assetSnapshot()}),p=await installInstagramPublication(db,x),r=await reserve(db,x);const mutations=[
 async()=>query(db,"update sanji_creator_evidence set detail=jsonb_set(detail,'{bio_content_available}','false') where source_kind='public_bio'"),
 async()=>query(db,"update sanji_creator_evidence set detail=jsonb_set(detail,'{bio}','\"협업 문의 없음\"') where source_kind='public_bio'"),
 async()=>query(db,"update sanji_creator_evidence set detail=jsonb_set(detail,'{bio}',$1) where source_kind='public_bio'",[JSON.stringify('협업 거절 '+p.detail.bio)]),
 async()=>query(db,"update sanji_creator_evidence set detail=jsonb_set(detail,'{bio}',$1) where source_kind='public_bio'",[JSON.stringify(p.detail.bio+' 다른 협업 other@example.com')]),
 async()=>query(db,"update sanji_creator_evidence set source_ref='unverified_import' where source_kind='public_bio'"),
 async()=>query(db,"update sanji_creator_evidence set source_provider='unknown' where source_kind='public_bio'"),
 async()=>query(db,"insert into sanji_creator_evidence(owner,creator_id,source_kind,source_provider,source_url,source_ref,detail) values($1,$2,'public_bio','instagram_public',$3,'manual_public_bio',$4)",[owner,cid,p.url,{...p.detail,bio:'소개 없음',bio_checked_at:new Date().toISOString()}]),
 async()=>query(db,"insert into sanji_creator_evidence(owner,creator_id,source_kind,source_provider,source_url,source_ref,detail) values($1,$2,'public_bio','instagram_public',$3,'manual_public_bio',$4)",[owner,cid,p.url,{...p.detail,bio:'협업 other@example.com'}]),
 async()=>query(db,"update sanji_creator_evidence set detail=jsonb_set(detail,'{bio_checked_at}','\"2000-01-01T00:00:00.000Z\"') where source_kind='public_bio'")
 ];for(const mutate of mutations){await db.exec('begin');await mutate();await assert.rejects(()=>begin(db,x,r),/bio|publication/);await db.exec('rollback');}await query(db,"insert into sanji_creator_evidence(owner,creator_id,source_kind,source_provider,source_url,source_ref,detail) values($1,$2,'public_bio','instagram_public',$3,'manual_public_bio',$4)",[other,cid,p.url,{...p.detail,bio:'removed'}]);assert.equal((await begin(db,x,r)).ready,true);}finally{await db.close();}});
test('SQL criteria schema is exact, new imports reject legacy grants, and dispatch rechecks 200k ceiling',async()=>{const db=await setup();try{for(const mutate of [s=>s.recipientCriteria.audienceBounds.youtube.maximum=500000,s=>s.recipientCriteria.targets.youtube=51,s=>s.recipientCriteria.maxEmailsPerCreator=2,s=>s.recipientCriteria.approvalSource='',s=>s.recipientCriteria.extra=true,s=>{s.version=1;delete s.recipientCriteria;}]){const s=structuredClone(snapshot());mutate(s);sealSnapshot(s);await assert.rejects(()=>rpc(db,'configure',owner,0,{data:s},policy),/recipient|criteria/);}const x=await ready(db);await assert.rejects(()=>reserve(db,{...x,plan:{...x.plan,recipientCriteria:{...x.plan.recipientCriteria,approvalSource:'different grant'}}}),/recipient criteria/);await query(db,"update sanji_daily_outreach_candidates set snapshot=jsonb_set(snapshot,'{audience}','200001')");await assert.rejects(()=>reserve(db,x),/recipient audience outside current criteria/);assert.equal((await query(db,'select count(*)::int n from sanji_outbox'))[0].n,0);}finally{await db.close();}});
